update public.question_solutions set explanation_markdown='A potência aumenta de 2 para 3 e o novo expoente passa a dividir o coeficiente. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado. A resolução abaixo mostra a decisão principal e a checagem necessária.' where question_id='40000000-0000-4000-8000-000000099001';
