update public.question_hints set content_markdown='Use as derivadas de $e^x$: todas valem $e^x$ e assumem valor $1$ no centro $0$.', sort_order=3 where id='60000000-0000-4000-8000-000000992363';
update public.question_solutions set explanation_markdown='Use as derivadas de $e^x$: todas valem $e^x$ e assumem valor $1$ no centro $0$. A alternativa correta é a única que aplica essa relação com todas as condições exigidas. As demais representam erros usuais: alterar um sinal, usar uma fórmula sem a hipótese necessária ou concluir antes de verificar o resultado. A resolução abaixo mostra a decisão principal e a checagem necessária.' where question_id='40000000-0000-4000-8000-000000099236';
